const [activeId, setActiveId] = useState('home')
const { profile } = useProfile()
const notifications = useNotifications()
const title = PAGE_TITLES[activeId] ?? ''

return (
  <IosenseShell
    activeId={activeId}
    onNavigate={(id) => setActiveId(resolveSection(id, SECTION_DEFAULTS))}
    trail={buildTrail(activeId, title, { items: NAV, pageTitles: PAGE_TITLES })}
    profile={profile}
    notifications={notifications.items}
    unreadCount={notifications.unreadCount}
    onOpenNotifications={() => setActiveId('notifications')}
  >
    <div style={{ padding: '16px 0' }}>
      <YourPage />
    </div>
  </IosenseShell>
)

const [pinned, setPinned] = useState(true)
const { preference, setPreference } = useAppTheme()

<IosenseShell
  {...rest}
  isPinned={pinned}
  onPinnedChange={setPinned}
  preference={preference}
  onPreferenceChange={setPreference}
>
  <YourPage />
</IosenseShell>

